// src/engine/py/tkinter/_text.py?raw
var _text_default = "# The Text widget: a field for many lines, with tags (colours and fonts of parts of the text), marks, the\n# selection, search, undo and the clipboard. Places are \"line.column\": \"1.0\" is the start, END is the end.\n# The page draws the coloured parts over the field (tk-text.tsx) and sends the new text (Edit) and the\n# selection (Selection) of the student.\nfrom tkinter import _style\nfrom tkinter._core import BASE_OPTIONS, TclError, app, touch\nfrom tkinter._events import Event\nfrom tkinter._fields import Linked\nfrom tkinter._widgets import Widget\n\n_TEXT_OPTIONS = dict(BASE_OPTIONS)\n_TEXT_OPTIONS.update(\n    {\n        \"autoseparators\": 1,\n        \"background\": \"SystemWindow\",\n        \"blockcursor\": 0,\n        \"borderwidth\": 1,\n        \"endline\": \"\",\n        \"exportselection\": 1,\n        \"font\": \"TkFixedFont\",\n        \"foreground\": \"SystemWindowText\",\n        \"height\": 24,\n        \"inactiveselectbackground\": \"SystemButtonFace\",\n        \"insertbackground\": \"SystemWindowText\",\n        \"insertborderwidth\": 0,\n        \"insertofftime\": 300,\n        \"insertontime\": 600,\n        \"insertunfocussed\": \"none\",\n        \"insertwidth\": 2,\n        \"maxundo\": 0,\n        \"padx\": 1,\n        \"pady\": 1,\n        \"relief\": \"sunken\",\n        \"selectbackground\": \"SystemHighlight\",\n        \"selectborderwidth\": 0,\n        \"selectforeground\": \"SystemHighlightText\",\n        \"setgrid\": 0,\n        \"spacing1\": 0,\n        \"spacing2\": 0,\n        \"spacing3\": 0,\n        \"startline\": \"\",\n        \"state\": \"normal\",\n        \"tabs\": \"\",\n        \"tabstyle\": \"tabular\",\n        \"undo\": 0,\n        \"width\": 80,\n        \"wrap\": \"char\",\n        \"xscrollcommand\": \"\",\n        \"yscrollcommand\": \"\",\n    }\n)\n\n# Options of a tag. The page shows foreground, background, font, underline and overstrike.\n_TAG_OPTIONS = (\n    \"background foreground font underline overstrike justify relief borderwidth lmargin1 lmargin2 rmargin \"\n    \"spacing1 spacing2 spacing3 offset elide wrap selectbackground selectforeground tabs bgstipple fgstipple\"\n).split()\n_TAG_COLORS = (\"background\", \"foreground\", \"selectbackground\", \"selectforeground\")\n\nSEL = \"sel\"\n# Names of the virtual events that the Text does itself (event_generate).\n_ACTIONS = (\"Cut\", \"Copy\", \"Paste\", \"Clear\", \"SelectAll\", \"Undo\", \"Redo\")\n\n\ndef _shift(position, start, removed, added, stays):\n    \"\"\"A place in the text after `removed` characters at `start` became `added` characters.\"\"\"\n    if position < start or (position == start and stays):\n        return position\n    if position < start + removed:\n        return start + added if not stays else start\n    return position - removed + added\n\n\nclass _Tag:\n    def __init__(self):\n        self.opts = {}\n        self.ranges = []  # [start, end] in characters, sorted, not empty, not touching\n        self.binds = None\n\n    def add(self, start, end):\n        if end <= start:\n            return\n        found = []\n        for a, b in sorted(self.ranges + [[start, end]]):\n            if found and a <= found[-1][1]:\n                found[-1][1] = max(found[-1][1], b)\n            else:\n                found.append([a, b])\n        self.ranges = found\n\n    def remove(self, start, end):\n        found = []\n        for a, b in self.ranges:\n            if b <= start or a >= end:\n                found.append([a, b])\n                continue\n            if a < start:\n                found.append([a, start])\n            if b > end:\n                found.append([end, b])\n        self.ranges = found\n\n\nclass Text(Widget):\n    \"\"\"A field for many lines of text. Places are \"line.column\": \"1.0\" is the start, END is the end.\"\"\"\n\n    _kind = \"Text\"\n    _class = \"Text\"\n    _defaults = _TEXT_OPTIONS\n    _states = (\"disabled\", \"normal\")\n\n    def _init(self):\n        self._value = \"\"\n        self._tags = {SEL: _Tag()}\n        self._tag_order = [SEL]\n        self._marks = {\"insert\": 0, \"current\": 0}\n        self._gravity = {\"insert\": \"right\", \"current\": \"right\"}\n        self._sel_rev = 0\n        self._modified = False\n        self._undo = []\n        self._redo = []\n        self.yview = Linked(self, Text._yview)\n        self.xview = Linked(self, Text._yview)\n\n    # ── places ──\n\n    def _offset(self, index):\n        text = self._value\n        name = str(index) if not isinstance(index, float) else \"%.1f\" % index\n        shift = 0\n        for sign in (\"+\", \"-\"):\n            at = name.find(sign, 1)\n            if at > 0:\n                change = name[at + 1 :].strip()\n                for unit in (\"chars\", \"char\", \"c\"):\n                    if change.endswith(unit):\n                        change = change[: -len(unit)].strip()\n                        break\n                if not change.isdigit():\n                    raise TclError('bad text index \"%s\"' % name)\n                shift = int(change) if sign == \"+\" else -int(change)\n                name = name[:at].strip()\n        base = self._base(name, text)\n        return max(0, min(base + shift, len(text) + 1))\n\n    def _base(self, name, text):\n        if name == \"end\":\n            return len(text) + 1\n        if name in (\"sel.first\", \"sel.last\"):\n            ranges = self._tags[SEL].ranges\n            if not ranges:\n                raise TclError('text doesn\\'t contain any characters tagged with \"sel\"')\n            return ranges[0][0] if name == \"sel.first\" else ranges[-1][1]\n        if name.endswith(\".first\") or name.endswith(\".last\"):\n            tag = self._tags.get(name.rsplit(\".\", 1)[0])\n            if tag is not None and tag.ranges:\n                return tag.ranges[0][0] if name.endswith(\".first\") else tag.ranges[-1][1]\n        if name in self._marks:\n            return min(self._marks[name], len(text))\n        if \".\" in name:\n            line_text, column_text = name.split(\".\", 1)\n            if not line_text.isdigit() or not (column_text.isdigit() or column_text == \"end\"):\n                raise TclError('bad text index \"%s\"' % name)\n            lines = text.split(\"\\n\")\n            line = int(line_text)\n            if line < 1:\n                return 0\n            if line > len(lines):\n                return len(text) + 1\n            start = sum(len(lines[i]) + 1 for i in range(line - 1))\n            length = len(lines[line - 1])\n            column = length if column_text == \"end\" else min(int(column_text), length)\n            return start + column\n        raise TclError('bad text index \"%s\"' % name)\n\n    def _place(self, offset):\n        before = (self._value + \"\\n\")[:offset]\n        line = before.count(\"\\n\") + 1\n        column = len(before) - (before.rfind(\"\\n\") + 1)\n        return \"%d.%d\" % (line, column)\n\n    def index(self, index):\n        return self._place(self._offset(index))\n\n    def compare(self, index1, op, index2):\n        a = self._offset(index1)\n        b = self._offset(index2)\n        checks = {\"<\": a < b, \"<=\": a <= b, \"==\": a == b, \">=\": a >= b, \">\": a > b, \"!=\": a != b}\n        if op not in checks:\n            raise TclError('bad comparison operator \"%s\": must be <, <=, ==, >=, >, or !=' % op)\n        return checks[op]\n\n    # ── text ──\n\n    def get(self, index1, index2=None):\n        whole = self._value + \"\\n\"\n        start = self._offset(index1)\n        end = start + 1 if index2 is None else self._offset(index2)\n        return whole[start:end] if end > start else \"\"\n\n    def count(self, index1, index2, *args):\n        return (abs(self._offset(index2) - self._offset(index1)),)\n\n    def _editable(self):\n        return str(self._opts[\"state\"]) == \"normal\"\n\n    def _snapshot(self):\n        if _style.flag(self._opts[\"undo\"]):\n            ranges = {name: [list(r) for r in tag.ranges] for name, tag in self._tags.items()}\n            self._undo.append((self._value, ranges))\n            self._redo = []\n\n    def _replace(self, start, end, chars, tags=(), source=None):\n        \"\"\"Puts `chars` in place of the text from `start` to `end`: tags and marks move with the text.\"\"\"\n        removed = end - start\n        added = len(chars)\n        self._value = self._value[:start] + chars + self._value[end:]\n        for tag in self._tags.values():\n            moved = []\n            for a, b in tag.ranges:\n                # Text typed at the start or at the end of a tag does not get the tag, as in Tk.\n                a2 = _shift(a, start, removed, added, False)\n                b2 = _shift(b, start, removed, added, True)\n                if b2 > a2:\n                    moved.append([a2, b2])\n            tag.ranges = moved\n        for name in self._marks:\n            self._marks[name] = _shift(self._marks[name], start, removed, added, self._gravity.get(name) == \"left\")\n        for name in tags:\n            self._tag(name).add(start, start + added)\n        if source is None:\n            self._rev += 1\n        self._set_modified()\n        touch()\n\n    def insert(self, index, chars, *args):\n        if not self._editable():\n            return\n        self._snapshot()\n        self._insert(min(self._offset(index), len(self._value)), chars, args)\n\n    def _insert(self, at, chars, args):\n        # insert(END, \"text\", \"tag\", \"more text\", (\"tag1\", \"tag2\")…)\n        pieces = [(chars, args[0] if args else ())]\n        rest = list(args[1:])\n        while rest:\n            pieces.append((rest[0], rest[1] if len(rest) > 1 else ()))\n            rest = rest[2:]\n        for piece, tags in pieces:\n            text = _style.tcl_text(piece)\n            names = [tags] if isinstance(tags, str) else list(tags)\n            names = [n for name in names for n in str(name).split()]\n            self._replace(at, at, text, names)\n            at += len(text)\n\n    def delete(self, index1, index2=None):\n        if not self._editable():\n            return\n        start = min(self._offset(index1), len(self._value))\n        end = start + 1 if index2 is None else self._offset(index2)\n        end = min(end, len(self._value))\n        if end > start:\n            self._snapshot()\n            self._replace(start, end, \"\")\n\n    def replace(self, index1, index2, chars, *args):\n        if not self._editable():\n            return\n        start = min(self._offset(index1), len(self._value))\n        end = min(self._offset(index2), len(self._value))\n        self._snapshot()\n        self._replace(start, max(start, end), \"\")\n        self._insert(start, chars, args)\n\n    def _edit(self, text):\n        # The student changed the text: only the changed part is replaced, so the tags stay on the rest.\n        new = str(text)\n        old = self._value\n        if new == old:\n            return\n        head = 0\n        limit = min(len(old), len(new))\n        while head < limit and old[head] == new[head]:\n            head += 1\n        tail = 0\n        while tail < limit - head and old[len(old) - 1 - tail] == new[len(new) - 1 - tail]:\n            tail += 1\n        self._snapshot()\n        self._replace(head, len(old) - tail, new[head : len(new) - tail], (), self)\n\n    def _set_modified(self):\n        if not self._modified:\n            self._modified = True\n            self._virtual(\"Modified\")\n\n    def _virtual(self, name):\n        event = Event(\"Virtual\", self)\n        event._detail = name\n        self._fire(event)\n\n    def edit_modified(self, arg=None):\n        if arg is None:\n            return self._modified\n        flag = _style.flag(arg)\n        if flag != self._modified:\n            self._modified = flag\n            self._virtual(\"Modified\")\n\n    def edit_undo(self):\n        if not self._undo:\n            raise TclError(\"nothing to undo\")\n        self._restore(self._undo, self._redo)\n\n    def edit_redo(self):\n        if not self._redo:\n            raise TclError(\"nothing to redo\")\n        self._restore(self._redo, self._undo)\n\n    def _restore(self, source, target):\n        ranges = {name: [list(r) for r in tag.ranges] for name, tag in self._tags.items()}\n        target.append((self._value, ranges))\n        value, saved = source.pop()\n        self._value = value\n        for name, tag in self._tags.items():\n            tag.ranges = saved.get(name, [])\n        self._rev += 1\n        self._set_modified()\n        touch()\n\n    def edit_reset(self):\n        self._undo = []\n        self._redo = []\n\n    def edit_separator(self):\n        pass\n\n    def edit(self, *args):\n        if args and args[0] == \"undo\":\n            return self.edit_undo()\n        if args and args[0] == \"redo\":\n            return self.edit_redo()\n        if args and args[0] == \"reset\":\n            return self.edit_reset()\n        if args and args[0] == \"modified\":\n            return self.edit_modified(*args[1:])\n\n    # ── tags ──\n\n    def _tag(self, name):\n        name = str(name)\n        tag = self._tags.get(name)\n        if tag is None:\n            tag = _Tag()\n            self._tags[name] = tag\n            self._tag_order.append(name)\n        return tag\n\n    def _pairs(self, index1, args):\n        indexes = [index1] + list(args)\n        pairs = []\n        i = 0\n        while i < len(indexes):\n            start = min(self._offset(indexes[i]), len(self._value))\n            if i + 1 < len(indexes):\n                end = min(self._offset(indexes[i + 1]), len(self._value))\n            else:\n                end = min(start + 1, len(self._value))\n            pairs.append((start, end))\n            i += 2\n        return pairs\n\n    def tag_add(self, tagName, index1, *args):\n        tag = self._tag(tagName)\n        for start, end in self._pairs(index1, args):\n            tag.add(start, end)\n        if str(tagName) == SEL:\n            self._sel_rev += 1\n        touch()\n\n    def tag_remove(self, tagName, index1, index2=None, *args):\n        tag = self._tags.get(str(tagName))\n        if tag is None:\n            return\n        rest = ((index2,) if index2 is not None else ()) + args\n        for start, end in self._pairs(index1, rest):\n            tag.remove(start, end)\n        if str(tagName) == SEL:\n            self._sel_rev += 1\n        touch()\n\n    def tag_configure(self, tagName, cnf=None, **kw):\n        tag = self._tag(tagName)\n        options = dict(cnf) if isinstance(cnf, dict) else {}\n        options.update(kw)\n        if isinstance(cnf, str):\n            return self.tag_cget(tagName, cnf)\n        if not options:\n            return {name: tag.opts.get(name, \"\") for name in _TAG_OPTIONS}\n        for key, value in options.items():\n            name = str(key).lstrip(\"-\").rstrip(\"_\")\n            name = {\"bg\": \"background\", \"fg\": \"foreground\"}.get(name, name)\n            if name not in _TAG_OPTIONS:\n                raise TclError('unknown option \"-%s\"' % name)\n            if name in _TAG_COLORS and value != \"\":\n                _style.color(value)\n            elif name == \"font\" and value != \"\":\n                _style.font(value)\n            tag.opts[name] = value\n        touch()\n\n    tag_config = tag_configure\n\n    def tag_cget(self, tagName, option):\n        name = str(option).lstrip(\"-\")\n        name = {\"bg\": \"background\", \"fg\": \"foreground\"}.get(name, name)\n        if name not in _TAG_OPTIONS:\n            raise TclError('unknown option \"-%s\"' % name)\n        return self._tag(tagName).opts.get(name, \"\")\n\n    def tag_delete(self, tagName, *tagNames):\n        for name in (tagName,) + tagNames:\n            name = str(name)\n            if name == SEL:\n                self._tags[SEL] = _Tag()\n                continue\n            if name in self._tags:\n                del self._tags[name]\n                self._tag_order.remove(name)\n        touch()\n\n    def tag_names(self, index=None):\n        if index is None:\n            return tuple(self._tag_order)\n        at = self._offset(index)\n        return tuple(name for name in self._tag_order if any(a <= at < b for a, b in self._tags[name].ranges))\n\n    def tag_ranges(self, tagName):\n        tag = self._tags.get(str(tagName))\n        if tag is None:\n            return ()\n        found = []\n        for a, b in tag.ranges:\n            found.append(self._place(a))\n            found.append(self._place(b))\n        return tuple(found)\n\n    def tag_nextrange(self, tagName, index1, index2=None):\n        tag = self._tags.get(str(tagName))\n        start = self._offset(index1)\n        stop = len(self._value) + 1 if index2 is None else self._offset(index2)\n        for a, b in tag.ranges if tag is not None else []:\n            if a >= start and a < stop or a < start < b:\n                return (self._place(max(a, start)), self._place(b))\n        return ()\n\n    def tag_prevrange(self, tagName, index1, index2=None):\n        tag = self._tags.get(str(tagName))\n        start = self._offset(index1)\n        stop = 0 if index2 is None else self._offset(index2)\n        for a, b in reversed(tag.ranges if tag is not None else []):\n            if a < start and b > stop:\n                return (self._place(a), self._place(b))\n        return ()\n\n    def tag_raise(self, tagName, aboveThis=None):\n        name = str(tagName)\n        if name in self._tag_order:\n            self._tag_order.remove(name)\n            self._tag_order.append(name)\n            touch()\n\n    def tag_lower(self, tagName, belowThis=None):\n        name = str(tagName)\n        if name in self._tag_order:\n            self._tag_order.remove(name)\n            self._tag_order.insert(0, name)\n            touch()\n\n    def tag_bind(self, tagName, sequence, func, add=None):\n        # Clicks on the parts of the text do not come from the page yet: the binding is kept.\n        tag = self._tag(tagName)\n        tag.binds = (sequence, func)\n        return \"%d\" % id(func)\n\n    def tag_unbind(self, tagName, sequence, funcid=None):\n        self._tag(tagName).binds = None\n\n    # ── marks and selection ──\n\n    def mark_set(self, markName, index):\n        name = str(markName)\n        self._marks[name] = min(self._offset(index), len(self._value))\n        if name == \"insert\":\n            self._sel_rev += 1\n        touch()\n\n    def mark_unset(self, *markNames):\n        for name in markNames:\n            if str(name) not in (\"insert\", \"current\"):\n                self._marks.pop(str(name), None)\n\n    def mark_names(self):\n        return tuple(self._marks)\n\n    def mark_gravity(self, markName, direction=None):\n        if direction is None:\n            return self._gravity.get(str(markName), \"right\")\n        self._gravity[str(markName)] = _style.one_of(\"mark gravity\", direction, (\"left\", \"right\"))\n\n    def mark_next(self, index):\n        at = self._offset(index)\n        after = sorted((pos, name) for name, pos in self._marks.items() if pos >= at)\n        return after[0][1] if after else None\n\n    def mark_previous(self, index):\n        at = self._offset(index)\n        before = sorted((pos, name) for name, pos in self._marks.items() if pos < at)\n        return before[-1][1] if before else None\n\n    def _select_text(self, start, end, caret):\n        # The student selected text on the page.\n        size = len(self._value)\n        start = max(0, min(start, size))\n        end = max(start, min(end, size))\n        self._tags[SEL].ranges = [[start, end]] if end > start else []\n        self._marks[\"insert\"] = max(0, min(caret, size))\n        self._marks[\"current\"] = self._marks[\"insert\"]\n        self._virtual(\"Selection\")\n\n    def _selected_text(self):\n        ranges = self._tags[SEL].ranges\n        return self._value[ranges[0][0] : ranges[-1][1]] if ranges else \"\"\n\n    # ── search and view ──\n\n    def search(self, pattern, index, stopindex=None, forwards=None, backwards=None, exact=None, regexp=None, nocase=None, count=None, elide=None):\n        needle = str(pattern)\n        if needle == \"\":\n            raise TclError(\"can't search for an empty pattern\")\n        text = self._value\n        start = min(self._offset(index), len(text))\n        hay = text.lower() if nocase else text\n        key = needle.lower() if nocase else needle\n        found, length = self._find(hay, key, start, bool(backwards), bool(regexp), stopindex)\n        if found < 0:\n            return \"\"\n        if count is not None:\n            count.set(length)\n        return self._place(found)\n\n    def _find(self, hay, key, start, backwards, regexp, stopindex):\n        stop = None if stopindex is None else self._offset(stopindex)\n        if regexp:\n            import re\n\n            matches = []\n            at = 0\n            while at <= len(hay):\n                m = re.search(key, hay[at:])\n                if m is None:\n                    break\n                matches.append((at + m.start(0), len(m.group(0))))\n                at = at + m.start(0) + max(1, len(m.group(0)))\n            order = [m for m in matches if m[0] < start][::-1] + [m for m in matches if m[0] >= start][::-1] if backwards else [m for m in matches if m[0] >= start] + [m for m in matches if m[0] < start]\n        else:\n            if backwards:\n                spot = hay.rfind(key, 0, start)\n                if spot < 0 and stop is None:\n                    spot = hay.rfind(key, start)\n            else:\n                spot = hay.find(key, start)\n                if spot < 0 and stop is None:\n                    spot = hay.find(key, 0, start)\n            order = [] if spot < 0 else [(spot, len(key))]\n        for spot, length in order:\n            if stop is not None and (spot > stop if not backwards else spot < stop):\n                continue\n            return spot, length\n        return -1, 0\n\n    def see(self, index):\n        pass\n\n    def _yview(self, *args):\n        if not args:\n            return (0.0, 1.0)\n\n    def yview_moveto(self, fraction):\n        pass\n\n    def yview_scroll(self, number, what):\n        pass\n\n    xview_moveto = yview_moveto\n    xview_scroll = yview_scroll\n\n    def bbox(self, index):\n        return None\n\n    def dlineinfo(self, index):\n        return None\n\n    # ── virtual events: <<Copy>>, <<Paste>>… ──\n\n    def event_generate(self, sequence, **kw):\n        Widget.event_generate(self, sequence, **kw)\n        text = str(sequence)\n        if text.startswith(\"<<\") and text.endswith(\">>\") and text[2:-2] in _ACTIONS:\n            getattr(self, \"_do_\" + text[2:-2].lower())()\n\n    def _do_copy(self):\n        chosen = self._selected_text()\n        if chosen:\n            app.clipboard = chosen\n\n    def _do_cut(self):\n        chosen = self._selected_text()\n        if chosen and self._editable():\n            app.clipboard = chosen\n            self.delete(\"sel.first\", \"sel.last\")\n\n    def _do_paste(self):\n        if not self._editable() or app.clipboard == \"\":\n            return\n        if self._tags[SEL].ranges:\n            self.delete(\"sel.first\", \"sel.last\")\n        self.insert(\"insert\", app.clipboard)\n\n    def _do_clear(self):\n        if self._tags[SEL].ranges:\n            self.delete(\"sel.first\", \"sel.last\")\n\n    def _do_selectall(self):\n        self.tag_add(SEL, \"1.0\", \"end\")\n\n    def _do_undo(self):\n        if self._undo:\n            self.edit_undo()\n\n    def _do_redo(self):\n        if self._redo:\n            self.edit_redo()\n\n    # ── page ──\n\n    def _text(self):\n        return self._value\n\n    def _styles(self):\n        # The parts of the text with the look of their tags: [start, end, colour, background, font, underline, overstrike].\n        shown = [name for name in self._tag_order if name != SEL and self._tags[name].ranges and self._tags[name].opts]\n        cuts = set()\n        for name in shown:\n            for a, b in self._tags[name].ranges:\n                cuts.add(a)\n                cuts.add(b)\n        cuts = sorted(cuts)\n        parts = []\n        for i in range(len(cuts) - 1):\n            a, b = cuts[i], cuts[i + 1]\n            look = {}\n            for name in shown:\n                if any(x <= a and b <= y for x, y in self._tags[name].ranges):\n                    look.update({k: v for k, v in self._tags[name].opts.items() if v != \"\"})\n            if look:\n                parts.append(self._part(a, b, look))\n        return parts\n\n    def _part(self, a, b, look):\n        font = \"\"\n        if \"font\" in look:\n            font = _style.font(look[\"font\"])[0]\n        return [\n            a,\n            b,\n            _style.color(look.get(\"foreground\", \"\")),\n            _style.color(look.get(\"background\", \"\")),\n            font,\n            _style.flag(look.get(\"underline\", 0)),\n            _style.flag(look.get(\"overstrike\", 0)),\n        ]\n\n    def _scene(self):\n        scene = Widget._scene(self)\n        ranges = self._tags[SEL].ranges\n        sel = self._tags[SEL]\n        scene[\"textStyle\"] = {\n            \"parts\": self._styles(),\n            \"selection\": [ranges[0][0], ranges[-1][1]] if ranges else [self._marks[\"insert\"], self._marks[\"insert\"]],\n            \"selectionRev\": self._sel_rev,\n            \"selectionColor\": _style.color(sel.opts.get(\"background\", \"\") or self._opts[\"selectbackground\"]),\n        }\n        return scene\n";
// src/engine/py/tkinter/_lists.py?raw
var _lists_default = "# Lists and choices: Listbox (rows to choose), Spinbox (a field with arrows), Combobox of ttk (a field with a\n# drop-down list) and Scrollbar. The page sends the chosen rows (Pick), the arrows (Spin) and the typed text\n# (Edit); a Scrollbar scrolls its widget on the page itself (tk-lists.tsx).\nfrom tkinter import _style\nfrom tkinter._core import BASE_OPTIONS, TclError, touch\nfrom tkinter._events import Event\nfrom tkinter._fields import _ENTRY_OPTIONS, Entry, Linked\nfrom tkinter._vars import Variable\nfrom tkinter._widgets import Widget\n\n_LISTBOX_OPTIONS = dict(BASE_OPTIONS)\n_LISTBOX_OPTIONS.update(\n    {\n        \"activestyle\": \"dotbox\",\n        \"background\": \"SystemWindow\",\n        \"borderwidth\": 1,\n        \"disabledforeground\": \"SystemDisabledText\",\n        \"exportselection\": 1,\n        \"font\": \"TkDefaultFont\",\n        \"foreground\": \"SystemWindowText\",\n        \"height\": 10,\n        \"highlightthickness\": 1,\n        \"justify\": \"left\",\n        \"listvariable\": \"\",\n        \"relief\": \"sunken\",\n        \"selectbackground\": \"SystemHighlight\",\n        \"selectborderwidth\": 0,\n        \"selectforeground\": \"SystemHighlightText\",\n        \"selectmode\": \"browse\",\n        \"setgrid\": 0,\n        \"state\": \"normal\",\n        \"width\": 20,\n        \"xscrollcommand\": \"\",\n        \"yscrollcommand\": \"\",\n    }\n)\n\n_MODES = (\"single\", \"browse\", \"multiple\", \"extended\")\n_ITEM_OPTIONS = (\"background\", \"foreground\", \"selectbackground\", \"selectforeground\")\n\n\ndef _virtual(widget, name):\n    event = Event(\"Virtual\", widget)\n    event._detail = name\n    widget._fire(event)\n\n\ndef tcl_list(value):\n    \"\"\"Items of a Tcl list: a tuple or list as it is, a text split by spaces (\"{two words}\" is one item).\"\"\"\n    if isinstance(value, (list, tuple)):\n        return [_style.tcl_text(v) for v in value]\n    text = _style.tcl_text(value)\n    if text.startswith(\"(\") and text.endswith(\")\"):\n        # str() of a tuple in a StringVar: ('a', 'b')\n        inner = text[1:-1]\n        return [part.strip().strip(\"'\\\"\") for part in inner.split(\",\") if part.strip()]\n    items = []\n    word = \"\"\n    depth = 0\n    for char in text:\n        if char == \"{\":\n            if depth > 0:\n                word += char\n            depth += 1\n        elif char == \"}\" and depth > 0:\n            depth -= 1\n            if depth > 0:\n                word += char\n        elif char in \" \\t\\n\" and depth == 0:\n            if word:\n                items.append(word)\n            word = \"\"\n        else:\n            word += char\n    if word:\n        items.append(word)\n    return items\n\n\nclass Listbox(Widget):\n    \"\"\"A list of rows: the student chooses one or more of them (`curselection()`).\"\"\"\n\n    _kind = \"Listbox\"\n    _class = \"Listbox\"\n    _defaults = _LISTBOX_OPTIONS\n    _states = (\"disabled\", \"normal\")\n\n    def _init(self):\n        self._items = []  # [text, {options}]\n        self._chosen = []\n        self._active = 0\n        self._anchor = 0\n        self.yview = Linked(self, Listbox._view)\n        self.xview = Linked(self, Listbox._view)\n\n    def _changed(self, name, old, value):\n        Widget._changed(self, name, old, value)\n        if name == \"listvariable\":\n            if isinstance(old, Variable):\n                old._unlink(self)\n            if isinstance(value, Variable):\n                value._link(self)\n                self._items = [[text, {}] for text in tcl_list(value._value)]\n        elif name == \"selectmode\":\n            _style.one_of(\"select mode\", value, _MODES + (\"\",))\n\n    def _list_rows(self):\n        variable = self._opts.get(\"listvariable\")\n        if isinstance(variable, Variable):\n            texts = tcl_list(variable._value)\n            if [item[0] for item in self._items] != texts:\n                self._items = [[text, {}] for text in texts]\n                self._chosen = [i for i in self._chosen if i < len(texts)]\n        return self._items\n\n    def _store(self):\n        variable = self._opts.get(\"listvariable\")\n        if isinstance(variable, Variable):\n            variable._store(tuple(item[0] for item in self._items), None)\n        touch()\n\n    def _index(self, index, end_is_size=True):\n        rows = self._list_rows()\n        if isinstance(index, int) and not isinstance(index, bool):\n            return index\n        name = str(index)\n        if name == \"end\":\n            return len(rows) if end_is_size else max(0, len(rows) - 1)\n        if name == \"active\":\n            return self._active\n        if name == \"anchor\":\n            return self._anchor\n        if name.startswith(\"@\"):\n            return 0\n        if name.lstrip(\"-\").isdigit():\n            return int(name)\n        raise TclError('bad listbox index \"%s\": must be active, anchor, end, @x,y, or a number' % name)\n\n    def index(self, index):\n        return self._index(index)\n\n    def size(self):\n        return len(self._list_rows())\n\n    def insert(self, index, *elements):\n        rows = self._list_rows()\n        at = max(0, min(self._index(index), len(rows)))\n        for offset, element in enumerate(elements):\n            rows.insert(at + offset, [_style.tcl_text(element), {}])\n        self._chosen = [i + len(elements) if i >= at else i for i in self._chosen]\n        self._rev += 1\n        self._store()\n\n    def delete(self, first, last=None):\n        rows = self._list_rows()\n        start = self._index(first, False)\n        end = start if last is None else self._index(last, False)\n        if start < 0 or end < start:\n            return\n        count = len(rows[start : end + 1])\n        del rows[start : end + 1]\n        self._chosen = [i - count if i > end else i for i in self._chosen if i < start or i > end]\n        self._rev += 1\n        self._store()\n\n    def get(self, first, last=None):\n        rows = self._list_rows()\n        start = self._index(first, False)\n        if last is None:\n            return rows[start][0] if 0 <= start < len(rows) else \"\"\n        end = self._index(last, False)\n        return tuple(item[0] for item in rows[max(0, start) : end + 1])\n\n    def curselection(self):\n        return tuple(sorted(self._chosen))\n\n    def selection_set(self, first, last=None):\n        rows = self._list_rows()\n        start = self._index(first, False)\n        end = start if last is None else self._index(last, False)\n        for i in range(max(0, start), min(end, len(rows) - 1) + 1):\n            if i not in self._chosen:\n                self._chosen.append(i)\n        self._rev += 1\n        touch()\n\n    select_set = selection_set\n\n    def selection_clear(self, first, last=None):\n        start = self._index(first, False)\n        end = start if last is None else self._index(last, False)\n        self._chosen = [i for i in self._chosen if i < start or i > end]\n        self._rev += 1\n        touch()\n\n    select_clear = selection_clear\n\n    def selection_includes(self, index):\n        return self._index(index, False) in self._chosen\n\n    select_includes = selection_includes\n\n    def selection_anchor(self, index):\n        self._anchor = self._index(index, False)\n\n    select_anchor = selection_anchor\n\n    def activate(self, index):\n        self._active = max(0, min(self._index(index, False), max(0, len(self._list_rows()) - 1)))\n        touch()\n\n    def nearest(self, y):\n        return max(0, min(int(_style.number(y)) // 16, len(self._list_rows()) - 1))\n\n    def see(self, index):\n        pass\n\n    def _view(self, *args):\n        if not args:\n            return (0.0, 1.0)\n\n    def yview_moveto(self, fraction):\n        pass\n\n    def yview_scroll(self, number, what):\n        pass\n\n    xview_moveto = yview_moveto\n    xview_scroll = yview_scroll\n\n    def itemconfigure(self, index, cnf=None, **kw):\n        rows = self._list_rows()\n        at = self._index(index, False)\n        if not 0 <= at < len(rows):\n            raise TclError('item number \"%s\" out of range' % index)\n        options = dict(cnf) if isinstance(cnf, dict) else {}\n        options.update(kw)\n        for key, value in options.items():\n            name = {\"bg\": \"background\", \"fg\": \"foreground\"}.get(str(key), str(key))\n            if name not in _ITEM_OPTIONS:\n                raise TclError('unknown option \"-%s\"' % name)\n            _style.color(value)\n            rows[at][1][name] = value\n        touch()\n\n    itemconfig = itemconfigure\n\n    def itemcget(self, index, option):\n        rows = self._list_rows()\n        name = {\"bg\": \"background\", \"fg\": \"foreground\"}.get(str(option), str(option))\n        return rows[self._index(index, False)][1].get(name, \"\")\n\n    def _pick(self, items):\n        # The student chose rows on the page.\n        if str(self._opts[\"state\"]) == \"disabled\":\n            return\n        size = len(self._list_rows())\n        chosen = [i for i in items if 0 <= i < size]\n        if str(self._opts[\"selectmode\"]) in (\"single\", \"browse\"):\n            chosen = chosen[:1]\n        self._chosen = chosen\n        if chosen:\n            self._active = chosen[-1]\n            self._anchor = chosen[-1]\n        touch()\n        _virtual(self, \"ListboxSelect\")\n\n    def _selected_text(self):\n        rows = self._list_rows()\n        return \"\\n\".join(rows[i][0] for i in sorted(self._chosen) if i < len(rows))\n\n    def _scene(self):\n        scene = Widget._scene(self)\n        opts = self._opts\n        scene[\"list\"] = {\n            \"rows\": [\n                [text, _style.color(look.get(\"foreground\", \"\")), _style.color(look.get(\"background\", \"\"))] for text, look in self._list_rows()\n            ],\n            \"chosen\": sorted(self._chosen),\n            \"active\": self._active,\n            \"mode\": str(opts[\"selectmode\"]) or \"browse\",\n            \"selectBg\": _style.color(opts[\"selectbackground\"]),\n            \"selectFg\": _style.color(opts[\"selectforeground\"]),\n        }\n        return scene\n\n\n_SPINBOX_OPTIONS = dict(_ENTRY_OPTIONS)\n_SPINBOX_OPTIONS.update(\n    {\n        \"activebackground\": \"SystemButtonFace\",\n        \"buttonbackground\": \"SystemButtonFace\",\n        \"buttoncursor\": \"\",\n        \"buttondownrelief\": \"raised\",\n        \"buttonuprelief\": \"raised\",\n        \"command\": \"\",\n        \"format\": \"\",\n        \"from\": 0,\n        \"increment\": 1,\n        \"repeatdelay\": 400,\n        \"repeatinterval\": 100,\n        \"to\": 0,\n        \"values\": \"\",\n        \"wrap\": 0,\n    }\n)\n\n\nclass Spinbox(Entry):\n    \"\"\"A field with two arrows: they choose the next number (`from_`, `to`, `increment`) or the next of `values`.\"\"\"\n\n    _kind = \"Spinbox\"\n    _class = \"Spinbox\"\n    _defaults = _SPINBOX_OPTIONS\n\n    def _init(self):\n        Entry._init(self)\n        self._value = self._first()\n\n    def _changed(self, name, old, value):\n        Entry._changed(self, name, old, value)\n        if name in (\"from\", \"values\") and not isinstance(self._opts.get(\"textvariable\"), Variable):\n            self._value = self._first()\n            self._rev += 1\n\n    def _values(self):\n        values = self._opts.get(\"values\", \"\")\n        return tcl_list(values) if values not in (\"\", None) else []\n\n    def _format(self, number):\n        pattern = str(self._opts.get(\"format\", \"\"))\n        if pattern:\n            try:\n                return pattern % number\n            except (TypeError, ValueError):\n                pass\n        step = float(_style.number(self._opts[\"increment\"]))\n        low = float(_style.number(self._opts[\"from\"]))\n        if step == int(step) and low == int(low):\n            return str(int(round(number)))\n        return str(round(number, 10))\n\n    def _first(self):\n        values = self._values()\n        if values:\n            return values[0]\n        return self._format(float(_style.number(self._opts[\"from\"])))\n\n    def _spin(self, direction):\n        if str(self._opts[\"state\"]) == \"disabled\":\n            return\n        self._put(self._next(self.get(), direction), None)\n        command = self._opts.get(\"command\")\n        if callable(command):\n            command()\n\n    def _next(self, current, direction):\n        wrap = _style.flag(self._opts[\"wrap\"])\n        values = self._values()\n        if values:\n            at = values.index(current) if current in values else -1\n            at += direction\n            if at >= len(values):\n                at = 0 if wrap else len(values) - 1\n            if at < 0:\n                at = len(values) - 1 if wrap else 0\n            return values[at]\n        low = float(_style.number(self._opts[\"from\"]))\n        high = float(_style.number(self._opts[\"to\"]))\n        step = float(_style.number(self._opts[\"increment\"]))\n        try:\n            number = float(current) + direction * step\n        except ValueError:\n            number = low\n        if number > high:\n            number = low if wrap else high\n        if number < low:\n            number = high if wrap else low\n        return self._format(number)\n\n    def invoke(self, element):\n        self._spin(1 if str(element) == \"buttonup\" else -1)\n\n    def set(self, value):\n        self._put(_style.tcl_text(value), None)\n\n    def _scene(self):\n        scene = Entry._scene(self)\n        scene[\"list\"] = {\"rows\": [[v, \"\", \"\"] for v in self._values()], \"chosen\": [], \"active\": 0, \"mode\": \"spin\", \"selectBg\": \"\", \"selectFg\": \"\"}\n        return scene\n\n\n_COMBOBOX_OPTIONS = dict(_ENTRY_OPTIONS)\n_COMBOBOX_OPTIONS.update({\"height\": 10, \"postcommand\": \"\", \"values\": \"\", \"style\": \"\", \"class\": \"\", \"padding\": 0})\n\n\nclass Combobox(Entry):\n    \"\"\"A field with a drop-down list of `values` (ttk). `current()` is the number of the chosen value.\"\"\"\n\n    _kind = \"Combobox\"\n    _class = \"TCombobox\"\n    _defaults = _COMBOBOX_OPTIONS\n\n    def _values(self):\n        values = self._opts.get(\"values\", \"\")\n        return tcl_list(values) if values not in (\"\", None) else []\n\n    def current(self, newindex=None):\n        values = self._values()\n        if newindex is None:\n            text = self.get()\n            return values.index(text) if text in values else -1\n        at = int(newindex)\n        if not 0 <= at < len(values):\n            raise TclError(\"index %s out of range\" % newindex)\n        self._put(values[at], None)\n\n    def set(self, value):\n        self._put(_style.tcl_text(value), None)\n\n    def _editable(self):\n        return str(self._opts[\"state\"]) != \"disabled\"\n\n    def _pick(self, items):\n        values = self._values()\n        if not items or not 0 <= items[0] < len(values) or str(self._opts[\"state\"]) == \"disabled\":\n            return\n        self._put(values[items[0]], None)\n        _virtual(self, \"ComboboxSelected\")\n\n    def _scene(self):\n        scene = Entry._scene(self)\n        values = self._values()\n        scene[\"list\"] = {\"rows\": [[v, \"\", \"\"] for v in values], \"chosen\": [self.current()] if self.current() >= 0 else [], \"active\": 0, \"mode\": \"combo\", \"selectBg\": \"\", \"selectFg\": \"\"}\n        return scene\n\n\n_SCROLLBAR_OPTIONS = dict(BASE_OPTIONS)\n_SCROLLBAR_OPTIONS.update(\n    {\n        \"activebackground\": \"SystemButtonFace\",\n        \"activerelief\": \"raised\",\n        \"command\": \"\",\n        \"elementborderwidth\": -1,\n        \"jump\": 0,\n        \"orient\": \"vertical\",\n        \"repeatdelay\": 300,\n        \"repeatinterval\": 100,\n        \"troughcolor\": \"SystemScrollbar\",\n        \"width\": 17,\n    }\n)\n\n\nclass Scrollbar(Widget):\n    \"\"\"A scroll bar. It scrolls the widget of `command=text.yview` (or the widget with `yscrollcommand=bar.set`).\"\"\"\n\n    _kind = \"Scrollbar\"\n    _class = \"Scrollbar\"\n    _defaults = _SCROLLBAR_OPTIONS\n\n    def _init(self):\n        self._view = (0.0, 1.0)\n        self.set = Linked(self, Scrollbar._set)\n\n    def _set(self, first, last):\n        self._view = (float(first), float(last))\n\n    def get(self):\n        return self._view\n\n    def activate(self, index=None):\n        return None\n\n    def fraction(self, x, y):\n        return 0.0\n\n    def delta(self, deltax, deltay):\n        return 0.0\n\n    def identify(self, x, y):\n        return \"\"\n\n    def _target(self):\n        command = self._opts.get(\"command\")\n        if isinstance(command, Linked) and command.owner._alive:\n            return command.owner._id\n        option = \"yscrollcommand\" if str(self._opts[\"orient\"]).startswith(\"v\") else \"xscrollcommand\"\n        from tkinter._core import app\n\n        for widget in app.widgets:\n            linked = widget._opts.get(option)\n            if isinstance(linked, Linked) and linked.owner is self:\n                return widget._id\n        return 0\n\n    def _scene(self):\n        scene = Widget._scene(self)\n        scene[\"scroll\"] = {\n            \"target\": self._target(),\n            \"vertical\": str(self._opts[\"orient\"]).startswith(\"v\"),\n            \"trough\": _style.color(self._opts[\"troughcolor\"]),\n        }\n        return scene\n";
