/**
* The Python texts of the engine (`prelude.py`, `turtle.py`, `tkinter`), built into the package as strings. The
* browser worker and Node use the same texts, so the server checks a program with the same `turtle` and `tkinter`.
*/
var pythonLibrary = {
	[LibraryFiles.Turtle]: turtle_default,
	[LibraryFiles.Tkinter]: __init___default,
	[LibraryFiles.TkConstants]: constants_default,
	[LibraryFiles.TkMessagebox]: messagebox_default,
	[LibraryFiles.TkThemed]: ttk_default,
	[LibraryFiles.TkCanvas]: _canvas_default,
	[LibraryFiles.TkCore]: _core_default,
	[LibraryFiles.TkEvents]: _events_default,
	[LibraryFiles.TkPage]: _page_default,
	[LibraryFiles.TkStyle]: _style_default,
	[LibraryFiles.TkVariables]: _vars_default,
	[LibraryFiles.TkFields]: _fields_default,
	[LibraryFiles.TkWidgets]: _widgets_default,
	[LibraryFiles.TkWindows]: _windows_default,
	[LibraryFiles.TkText]: _text_default,
	[LibraryFiles.TkLists]: _lists_default,
	[LibraryFiles.TkMenus]: _menus_default,
	[LibraryFiles.TkImages]: _images_default,
	[LibraryFiles.TkFiledialog]: filedialog_default,
	[LibraryFiles.TkSimpledialog]: simpledialog_default,
	[LibraryFiles.TkColorchooser]: colorchooser_default,
	[LibraryFiles.TkScrolledtext]: scrolledtext_default,
	[LibraryFiles.TkThemedWidgets]: _themed_default,
	[LibraryFiles.TkFont]: font_default
};
var pythonPrelude = prelude_default;
/** Sources for `loadEngine`. `wasmUrl`: the address of `micropython.wasm` in a browser build; `undefined` in Node. */
var engineSources = (wasmUrl) => ({
	wasmUrl,
	prelude: prelude_default,
	library: pythonLibrary
});
/** The engine in Node (tests, server checks): MicroPython finds its `.wasm` next to its own module. */
var loadNodeEngine = () => loadEngine(engineSources(void 0));
